output:
2194	            const int32_t in_phase = phase % period;
2195	            const bool in_dash = in_phase < on;
2196	            const int32_t left = in_dash ? (on - in_phase) : (period - in_phase);
2197	            int32_t step = left;
2198	
2199	            if (step > len - t) {
2200	                step = len - t;
2201	            }
2202	            if (step <= 0) {
2203	                break;
2204	            }
2205	            if (in_dash) {
2206	                const int32_t x0 = ax + (int32_t)((int64_t)dx * t / len);
2207	                const int32_t y0 = ay + (int32_t)((int64_t)dy * t / len);
2208	                const int32_t x1 = ax + (int32_t)((int64_t)dx * (t + step) / len);
2209	                const int32_t y1 = ay + (int32_t)((int64_t)dy * (t + step) / len);
2210	
2211	#if VMAP_RENDER_AA
2212	                /* 一个 dash = 一条短丝带（一次多边形 + 两端圆帽，半径 hw）。
2213	                 * 不再"粗线 + 两端 (w+1)/2 圆盘"；dash 之间各自独立，不会连起来。 */
2214	                {
2215	                    vmap_point_t seg[2];
2216	
2217	                    seg[0].x = x0;
2218	                    seg[0].y = y0;
2219	                    seg[1].x = x1;
2220	                    seg[1].y = y1;
2221	                    stroke_ribbon_aa_chunk(c, seg, 2, width, color, true, true);
2222	                }
2223	#else
2224	                vmap_render_draw_thick_line(c, x0, y0, x1, y1, width, color);
2225	#endif
2226	            }
2227	            t += step;
2228	            phase += step;
2229	        }
2230	    }
2231	}
