2233	static void draw_road_feature_line(vmap_canvas_t * c, const vmap_feature_t * f,
2234	    float base_x, float base_y, float u, int32_t width, uint16_t color,
2235	    int32_t dash_on, int32_t dash_off, vmap_point_t * scratch, int scratch_cap)
2236	{
2237	    int32_t n;
2238	    int32_t i;
2239	
2240	    if (!f || f->point_count < 2 || width < 1 || !scratch || scratch_cap < 2) {
2241	        return;
2242	    }
2243	
2244	    n = f->point_count;
2245	    if (n > scratch_cap) {
2246	        n = scratch_cap;
2247	    }
2248	
2249	    for (i = 0; i < n; i++) {
2250	        scratch[i].x = (int32_t)lroundf(base_x + vmap_feature_x(f, (uint16_t)i) * u);
2251	        scratch[i].y = (int32_t)lroundf(base_y + vmap_feature_y(f, (uint16_t)i) * u);
2252	    }
2253	
2254	    /* 早退：完全写不到就不必简化、不必描边、不必点圆盘。外扩 = 描边半宽 + AA 余量
2255	     * （保守方向），且必须在 VMAP_ROAD_SIMPLIFY 之前 —— 那一步也是纯浪费。 */
2256	    {
2257	        const int32_t pad = (width + 1) / 2 + 2;
2258	        int32_t bx1 = scratch[0].x;
2259	        int32_t by1 = scratch[0].y;
2260	        int32_t bx2 = scratch[0].x;
2261	        int32_t by2 = scratch[0].y;
2262	
2263	        for (i = 1; i < n; i++) {
2264	            if (scratch[i].x < bx1) { bx1 = scratch[i].x; }
2265	            if (scratch[i].x > bx2) { bx2 = scratch[i].x; }
2266	            if (scratch[i].y < by1) { by1 = scratch[i].y; }
2267	            if (scratch[i].y > by2) { by2 = scratch[i].y; }
2268	        }
2269	        if (!box_may_write(c, bx1 - pad, by1 - pad, bx2 + pad, by2 + pad)) {
2270	            return;
2271	        }
2272	    }
2273	
2274	#if VMAP_ROAD_SIMPLIFY
2275	    n = simplify_road_polyline(scratch, n, VMAP_ROAD_MIN_SEG_PX,
2276	        VMAP_ROAD_MAX_DEV_PX);
2277	    if (n >= 4) {
2278	        n = simplify_road_polyline(scratch, n, VMAP_ROAD_MIN_SEG_PX,
2279	            VMAP_ROAD_MAX_DEV_PX);
2280	    }
2281	#endif
2282	
2283	    /* 面状 highway 残渣（宽环）不画，虚线也一样跳过。 */
2284	    if (road_ring_is_area(scratch, n)) {
2285	        return;
2286	    }
2287	
2288	    if (dash_on > 0 && dash_off > 0) {
2289	        draw_dashed_polyline(c, scratch, n, width, color, dash_on, dash_off);
2290	    } else {
2291	        draw_road_polyline(c, scratch, n, width, color);
2292	    }
2293	}
