2471	/** @brief 一条道路要素按"壳"或"芯"落笔（path 无壳；芯走虚线）。 */
2472	static void road_stroke_feature(vmap_canvas_t * c, const vmap_feature_t * f,
2473	    int cls, bool shell, float base_x, float base_y, float u, int32_t ws_q8,
2474	    vmap_point_t * scratch, int scratch_cap)
2475	{
2476	    const vmap_style_road_t * st;
2477	    int32_t core_w;
2478	    int32_t width;
2479	    int32_t dash_on = 0;
2480	    int32_t dash_off = 0;
2481	    uint16_t color;
2482	
2483	    if (!f || f->point_count < 2 || vmap_feature_is_closed(f)) {
2484	        return;
2485	    }
2486	
2487	    st = road_style_for(cls);
2488	    core_w = road_core_px((int32_t)st->w, ws_q8);
2489	
2490	    if (shell) {
2491	        /* path 是虚线无壳；支路（residential/service）芯只有 2~3px，
2492	         * 再套 1px 壳就变成"米色带白线"（WP-RD2 像素列实测）。
2493	         * 只给干道（motorway/primary/secondary/tertiary）画壳。 */
2494	        if (cls == VMAP_ROAD_PATH || core_w <= 3) {
2495	            return;
2496	        }
2497	        width = road_case_px(core_w, ws_q8);
2498	        color = RGB565(st->cr, st->cg, st->cb);
2499	    } else {
2500	        width = core_w;
2501	        color = RGB565(st->r, st->g, st->b);
2502	        if (cls == VMAP_ROAD_PATH) {
2503	            /* 虚线 5 实 / 4 虚（1× 设备像素，§3），随线宽倍率一起放大。 */
2504	            const int32_t ws10 = (ws_q8 * 10 + 128) >> 8;
2505	
2506	            dash_on = (5 * ws10 + 5) / 10;
2507	            dash_off = (4 * ws10 + 5) / 10;
2508	            if (dash_on < 2) {
2509	                dash_on = 2;
2510	            }
2511	            if (dash_off < 2) {
2512	                dash_off = 2;
2513	            }
2514	        }
2515	    }
2516	
2517	    draw_road_feature_line(c, f, base_x, base_y, u, width, color, dash_on,
2518	        dash_off, scratch, scratch_cap);
2519	}
