2570	/**
2571	 * @brief 道路层：低等级先画、高等级后画；每级"壳→芯"成对。
2572	 *
2573	 * STYLE.md §3 最后一条：路口处高等级自然压住低等级，不需要额外的连接处理。
2574	 * 每级内部仍是"先本级的全部壳、再本级的全部芯"，同一等级的路口不会被同级的
2575	 * 壳切断。绑定索引时两遍 pass 只按 `rec[0]` 过滤；未绑定/索引溢出时退回逐
2576	 * class 全层扫描（像素结果一致）。
2577	 */
2578	static void draw_road_layer(vmap_canvas_t * c, const vmap_tile_t * tile,
2579	    uint16_t extent, float base_x, float base_y, float scale,
2580	    vmap_point_t * scratch, int scratch_cap)
2581	{
2582	    const float u = 256.0f * scale / (float)extent;
2583	    const int32_t ws_q8 = road_width_scale_q8(scale);
2584	    int cls;
2585	
2586	    if (s_road_refs && s_road_ref_cap > 0) {
2587	        /* 一次扫描：装本瓦片 ROAD 层的要素记录起点。*/
2588	        vmap_feature_iter_t scan = vmap_tile_layer_iter(tile, VMAP_LAYER_ROAD);
2589	        const uint8_t * layer_end = scan.end;
2590	        int n = 0;
2591	        bool overflow = false;
2592	
2593	        while (n < s_road_ref_cap) {
2594	            const uint8_t * rec = scan.ptr;
2595	            vmap_feature_t f;
2596	
2597	            if (!vmap_feature_iter_next(&scan, &f)) {
2598	                break;
2599	            }
2600	            s_road_refs[n++].rec = rec;
2601	        }
2602	        if (n == s_road_ref_cap && scan.remaining > 0) {
2603	            overflow = true;
2604	        }
2605	
2606	        if (!overflow) {
2607	            for (cls = VMAP_ROAD_PATH; cls >= VMAP_ROAD_MOTORWAY; cls--) {
2608	                if (!vmap_style_road_visible((uint8_t)cls, scale)) {
2609	                    continue;
2610	                }
2611	                /* 壳 → 芯 成对；path 的壳在 road_stroke_feature() 里直接跳过。 */
2612	                road_stroke_refs(c, s_road_refs, n, layer_end, cls, true,
2613	                    base_x, base_y, u, ws_q8, scratch, scratch_cap);
2614	                road_stroke_refs(c, s_road_refs, n, layer_end, cls, false,
2615	                    base_x, base_y, u, ws_q8, scratch, scratch_cap);
2616	            }
2617	            return;
2618	        }
2619	    }
2620	
2621	    /* 回退：未绑定索引、cap<=0 或索引溢出时走原实现（逐 class 全层扫描）。 */
2622	    for (cls = VMAP_ROAD_PATH; cls >= VMAP_ROAD_MOTORWAY; cls--) {
2623	        if (!vmap_style_road_visible((uint8_t)cls, scale)) {
2624	            continue;
2625	        }
2626	        road_stroke_scan(c, tile, cls, true, base_x, base_y, u, ws_q8, scratch,
2627	            scratch_cap);
2628	        road_stroke_scan(c, tile, cls, false, base_x, base_y, u, ws_q8, scratch,
2629	            scratch_cap);
2630	    }
2631	}
