2656	 */
2657	void vmap_render_clear(vmap_canvas_t * c, uint16_t color)
2658	{
2659	    vmap_blit_surface_t surf;
2660	
2661	    if (!c || !c->buf) {
2662	        return;
2663	    }
2664	
2665	    /* 先问搬运后端（走 EPIC 时是一整块矩形一条命令）；它不可用或没通过自检
2666	     * 时，同一个调用会把 CPU 版本做完 —— 见 vmap_blit.h。 */
2667	    render_surface(c, &surf);
2668	    vmap_blit_fill(render_blit(), &surf, 0, 0, c->w, c->h, color);
2669	}
2670	
2671	/*
2672	 * 这里原有一个 `render_fill_span(row, x0, x1, color)`（成对写的一行填充）。
2673	 * scroll 改成"矩形 + 两条边"之后它没有调用者了 —— 补边现在走
2674	 * `vmap_blit_fill()`，CPU 那支的成对写等价物在 `vmap_blit.c` 的 `cpu_fill()`。
2675	 */
2676	
2677	void vmap_render_scroll(vmap_canvas_t * c, int32_t dx, int32_t dy, uint16_t fill)
2678	{
2679	    vmap_blit_surface_t surf;
2680	    vmap_blit_t * blit;
2681	    int32_t copy_w;
2682	    int32_t copy_h;
2683	    int32_t x0;
2684	    int32_t y0;
2685	
2686	    if (!c || !c->buf) {
2687	        return;
2688	    }
2689	
2690	    if (dx == 0 && dy == 0) {
2691	        return;
2692	    }
2693	
2694	    if (dx >= c->w || dx <= -c->w || dy >= c->h || dy <= -c->h) {
2695	        vmap_render_clear(c, fill);
2696	        return;
2697	    }
2698	
2699	    /*
2700	     * 原来这条是逐行 memmove + 逐行补边；现在拆成**一块矩形 + 两条边**，
2701	     * 这样整块矩形才有机会落到 EPIC 上（一条命令 vs 472 次函数调用）。
2702	     * 逐行版的代价是实打实的：使用过程一帧的 `cyc_begin` 里 92% 就是它
2703	     * （见 `[vperf] frame ... scr=`），单帧 164 ms。
2704	     *
2705	     * 语义与逐行版逐位相同：
2706	     *   拷贝区 = 目的 (x0,y0) ← 源 (x0+dx, y0+dy)，尺寸 (w−|dx|, h−|dy|)；
2707	     *   横向露出的 |dx| 列只覆盖**拷贝区那几行**，纵向露出的 |dy| 行整宽铺满。
2708	     * 次序必须是**先拷贝后填充**：露出的边落在源矩形的范围内（横向边在
2709	     * y 属于拷贝区时、纵向边在 x 属于拷贝区时），先填会把还没读的源像素盖掉。
2710	     * 逐行版之所以没这个问题，是因为它在同一行里也是先 memmove 后补边、
2711	     * 且行的方向按 dy 的符号选过（跨行的重叠只有那个方向是安全的）。
2712	     */
2713	    copy_w = c->w - (dx >= 0 ? dx : -dx);
2714	    copy_h = c->h - (dy >= 0 ? dy : -dy);
2715	    x0 = (dx > 0) ? 0 : -dx;
2716	    y0 = (dy > 0) ? 0 : -dy;
2717	
2718	    render_surface(c, &surf);
2719	    blit = render_blit();
2720	
2721	    (void)vmap_blit_copy(blit, &surf, x0, y0, &surf, x0 + dx, y0 + dy,
2722	        copy_w, copy_h);
2723	
2724	    if (dx > 0) {
2725	        (void)vmap_blit_fill(blit, &surf, c->w - dx, y0, dx, copy_h, fill);
2726	    } else if (dx < 0) {
2727	        (void)vmap_blit_fill(blit, &surf, 0, y0, -dx, copy_h, fill);
2728	    }
2729	
2730	    if (dy > 0) {
2731	        (void)vmap_blit_fill(blit, &surf, 0, c->h - dy, c->w, dy, fill);
2732	    } else if (dy < 0) {
2733	        (void)vmap_blit_fill(blit, &surf, 0, 0, c->w, -dy, fill);
2734	    }
2735	}
2736	
2737	static void fill_rect(vmap_canvas_t * c, int32_t x1, int32_t y1, int32_t x2,
2738	    int32_t y2, uint16_t color)
2739	{
2740	    int32_t y;
2741	
2742	    if (!c || x1 >= x2 || y1 >= y2) {
2743	        return;
2744	    }
2745	    if (x1 < 0) {
2746	        x1 = 0;
2747	    }
2748	    if (y1 < 0) {
2749	        y1 = 0;
2750	    }
2751	    if (x2 > c->w) {
2752	        x2 = c->w;
2753	    }
2754	    if (y2 > c->h) {
2755	        y2 = c->h;
2756	    }
2757	    if (x1 >= x2 || y1 >= y2) {
2758	        return;
2759	    }
2760	
2761	    for (y = y1; y < y2; y++) {
2762	        blend_span(c, x1, x2 - 1, y, color);
2763	    }
2764	}
