2766	/**
2767	 * @brief 将瓦片绘制到画布。
2768	 */
2769	void vmap_render_draw_tile(vmap_canvas_t * c, const vmap_tile_t * tile,
2770	    float base_x, float base_y, float scale, vmap_point_t * scratch, int scratch_cap)
2771	{
2772	    const vmap_style_t * style;
2773	    int32_t x1;
2774	    int32_t y1;
2775	    int32_t x2;
2776	    int32_t y2;
2777	
2778	    if (!c || !tile) {
2779	        return;
2780	    }
2781	
2782	    /* Vector layers do not cover every pixel. Track/route ribbons are stamped
2783	     * on top; without a bg fill, restamping leaves those pixels behind. */
2784	    x1 = (int32_t)floorf(base_x);
2785	    y1 = (int32_t)floorf(base_y);
2786	    x2 = (int32_t)ceilf(base_x + 256.0f * scale);
2787	    y2 = (int32_t)ceilf(base_y + 256.0f * scale);
2788	    fill_rect(c, x1, y1, x2, y2, vmap_style_bg565());
2789	
2790	    style = vmap_style_current();
2791	    uint16_t extent = vmap_tile_extent(tile);
2792	    const uint16_t forest = RGB565(style->forest_r, style->forest_g,
2793	        style->forest_b);
2794	    const uint16_t water = RGB565(style->water_r, style->water_g, style->water_b);
2795	
2796	    draw_land_layer(c, vmap_tile_layer_iter(tile, VMAP_LAYER_LAND), extent,
2797	        base_x, base_y, scale, scratch, scratch_cap);
2798	    draw_poly_layer(c, vmap_tile_layer_iter(tile, VMAP_LAYER_FOREST), extent,
2799	        base_x, base_y, scale, forest, 0, 0, scratch, scratch_cap);
2800	    draw_poly_layer(c, vmap_tile_layer_iter(tile, VMAP_LAYER_WATER), extent,
2801	        base_x, base_y, scale, water, 0, 0, scratch, scratch_cap);
2802	    draw_line_layer(c, vmap_tile_layer_iter(tile, VMAP_LAYER_WATERWAY), extent,
2803	        base_x, base_y, scale, scratch, scratch_cap);
2804	    draw_road_layer(c, tile, extent, base_x, base_y, scale, scratch, scratch_cap);
2805	}
