static inline uint16_t hex565(uint32_t rgb)
{
    return vr_rgb565((uint8_t)(rgb >> 16), (uint8_t)(rgb >> 8), (uint8_t)rgb);
}

/* 虚线：按弧长切"实/虚"子段，再交给 vr_line。
 * 不能按 1px 递进画 —— 那么短的段会被线宽撑成锯齿。 */
static void dashed_line(vr_canvas_t *c, const int32_t *xy, int n, int width,
                        uint16_t color, int on, int off)
{
    const int period = on + off;
    int phase = 0;

    for (int i = 0; i + 1 < n; i++) {
        const double ax = (double)xy[2 * i];
        const double ay = (double)xy[2 * i + 1];
        const double bx = (double)xy[2 * i + 2];
        const double by = (double)xy[2 * i + 3];
        const double dx = bx - ax;
        const double dy = by - ay;
        const int len = (int)(0.5 + sqrt(dx * dx + dy * dy));
        int t = 0;

        while (t < len) {
            const int in_phase = phase % period;
            const int in_dash = in_phase < on;
            const int left = in_dash ? (on - in_phase) : (period - in_phase);
            int step = left;

            if (step > len - t) {
                step = len - t;
            }
            if (in_dash) {
                int32_t seg[4];
                seg[0] = (int32_t)(ax + dx * t / len);
                seg[1] = (int32_t)(ay + dy * t / len);
                seg[2] = (int32_t)(ax + dx * (t + step) / len);
                seg[3] = (int32_t)(ay + dy * (t + step) / len);
                vr_line(c, seg, 2, width, color);
            }
            t += step;
            phase += step;
        }
    }
}

